// מילת הסוג שלפני מקום בטקסט (מנורמל), או null כשאין
function placeKind(text,s){
  const back=String(text||"").slice(Math.max(0,s-20),s);
  for(const [rx,k] of PLACE_KIND_HEADS) if(rx.test(back))return k;
  return null;
}
